// Report 5.2 — Integration Test. One object per test-case row. Every case starts from the seed data.
// steps: { as: 'student1' | 'student2' | 'student3' | 'manager' | 'admin' | 'guest', call: 'METHOD /path', body?, expect?: { status, body } }
const TEST_CASES = [
  {
    id: 'IT-01',
    description: 'Verify that login with valid credentials returns a token and the STUDENT role',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'An@12345' },
        expect: { status: 200, body: { role: 'STUDENT' } },
      },
    ],
  },
];

// Test Statistics sheet (Report 5.2) — Round 1 figures of the table in the brief.
const STATS = {
  passed: 0,
  failed: 0,
  pending: 0,
  na: 0,
  total: 0,
  testCoverage: 0,          // (Passed + Failed) × 100 / (Total − N/A), 2 decimals
  successfulCoverage: 0,    // Passed × 100 / (Total − N/A), 2 decimals
  round2Column: '',         // the column the Round 2 counters must count
};

