// Report 5.2 — Integration Test (Authentication · Booking · Lab management). 13 cases.
// Each case proves one integration: security filter ↔ controller ↔ service ↔ repository/DB ↔ mail service.
const TEST_CASES = [
  {
    id: 'IT-01',
    description: 'Verify that login with valid credentials returns a token and the STUDENT role',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'An@12345' },
        expect: { status: 200, body: { role: 'STUDENT' } },
      },
    ],
  },
  {
    id: 'IT-02',
    description: 'Verify that the 3rd consecutive wrong password locks the account (auth service ↔ users table)',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'wrong-1' },
        expect: { status: 401, body: { error: 'AUTH_INVALID' } },
      },
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'wrong-2' },
        expect: { status: 401, body: { error: 'AUTH_INVALID' } },
      },
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'wrong-3' },
        expect: { status: 401, body: { error: 'AUTH_INVALID' } },
      },
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'An@12345' },
        expect: { status: 423, body: { error: 'ACCOUNT_LOCKED' } },
      },
    ],
  },
  {
    id: 'IT-03',
    description: 'Verify that a successful login resets the failure counter',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      { call: 'POST /api/auth/login', body: { email: 'an@fpt.edu.vn', password: 'wrong-1' }, expect: { status: 401 } },
      { call: 'POST /api/auth/login', body: { email: 'an@fpt.edu.vn', password: 'wrong-2' }, expect: { status: 401 } },
      { call: 'POST /api/auth/login', body: { email: 'an@fpt.edu.vn', password: 'An@12345' }, expect: { status: 200 } },
      { call: 'POST /api/auth/login', body: { email: 'an@fpt.edu.vn', password: 'wrong-3' }, expect: { status: 401 } },
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'An@12345' },
        expect: { status: 200, body: { role: 'STUDENT' } },
      },
    ],
  },
  {
    id: 'IT-04',
    description: 'Verify that a confirmed booking is saved in the bookings table and a confirmation e-mail is sent',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 2 },
        expect: { status: 201, body: { code: 'BK0001', status: 'CONFIRMED' } },
      },
      {
        as: 'admin',
        call: 'GET /test/db/bookings',
        expect: {
          status: 200,
          body: { '0': { code: 'BK0001', email: 'an@fpt.edu.vn', labCode: 'LAB01', status: 'CONFIRMED' }, length: 1 },
        },
      },
      {
        as: 'admin',
        call: 'GET /test/outbox',
        expect: { status: 200, body: { '0': { to: 'an@fpt.edu.vn', subject: 'Booking confirmed', ref: 'BK0001' }, length: 1 } },
      },
    ],
  },
  {
    id: 'IT-05',
    description: 'Verify that a full lab puts the next student on the waitlist (PENDING) and e-mails "Added to waitlist"',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 2 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 2 },
        expect: { status: 201, body: { code: 'BK0002', status: 'PENDING' } },
      },
      {
        as: 'admin',
        call: 'GET /test/outbox',
        expect: { status: 200, body: { '1': { to: 'binh@fpt.edu.vn', subject: 'Added to waitlist' }, length: 2 } },
      },
    ],
  },
  {
    id: 'IT-06',
    description: 'Verify that the API rejects invalid input and missing/wrong credentials before reaching the service',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 22, duration: 1 },
        expect: { status: 400, body: { error: 'VALIDATION', field: 'startHour' } },
      },
      {
        as: 'guest',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 401, body: { error: 'UNAUTHENTICATED' } },
      },
      {
        as: 'manager',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 403, body: { error: 'FORBIDDEN' } },
      },
      { as: 'admin', call: 'GET /test/db/bookings', expect: { status: 200, body: { length: 0 } } },
    ],
  },
  {
    id: 'IT-07',
    description: 'Verify that an unknown lab code is reported as 404 by the lab repository',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB99', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 404, body: { error: 'LAB_NOT_FOUND' } },
      },
    ],
  },
  {
    id: 'IT-08',
    description: 'Verify that a student cannot hold two overlapping bookings in different labs',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 2 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 2 },
        expect: { status: 409, body: { error: 'OVERLAP' } },
      },
    ],
  },
  {
    id: 'IT-09',
    description: 'Verify that the weekly 6-hour limit from the service is returned as 422 WEEKLY_LIMIT',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-05', startHour: 9, duration: 1 },
        expect: { status: 422, body: { error: 'WEEKLY_LIMIT' } },
      },
    ],
  },
  {
    id: 'IT-10',
    description: 'Verify that GET /api/bookings/me returns only the caller’s bookings',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: { '0': { email: 'an@fpt.edu.vn' }, length: 1 } },
      },
    ],
  },
  {
    id: 'IT-11',
    description: 'Verify that cancelling a confirmed booking updates the database, promotes the waitlist and e-mails the promoted student',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 2 },
        expect: { status: 201, body: { code: 'BK0001', status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 2 },
        expect: { status: 201, body: { code: 'BK0002', status: 'PENDING' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200, body: { status: 'CANCELLED' } } },
      {
        as: 'admin',
        call: 'GET /test/db/bookings',
        expect: {
          status: 200,
          body: { '0': { code: 'BK0001', status: 'CANCELLED' }, '1': { code: 'BK0002', status: 'CONFIRMED' } },
        },
      },
      {
        as: 'admin',
        call: 'GET /test/outbox',
        expect: { status: 200, body: { '2': { to: 'binh@fpt.edu.vn', subject: 'Booking confirmed', ref: 'BK0002' }, length: 3 } },
      },
    ],
  },
  {
    id: 'IT-12',
    description: 'Verify that closing a lab cancels its confirmed AND pending bookings and e-mails every student',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 2 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 2 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student3',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 2 },
        expect: { status: 201, body: { status: 'PENDING' } },
      },
      {
        as: 'manager',
        call: 'PATCH /api/labs/LAB01',
        body: { status: 'CLOSED' },
        expect: { status: 200, body: { status: 'CLOSED', cancelled: 3 } },
      },
      {
        as: 'admin',
        call: 'GET /test/db/bookings',
        expect: {
          status: 200,
          body: { '0': { status: 'CANCELLED' }, '1': { status: 'CANCELLED' }, '2': { status: 'CANCELLED' } },
        },
      },
      {
        as: 'admin',
        call: 'GET /test/outbox',
        expect: { status: 200, body: { '5': { to: 'chi@fpt.edu.vn', subject: 'Lab closed - booking cancelled' }, length: 6 } },
      },
    ],
  },
  {
    id: 'IT-13',
    description: 'Verify that a STUDENT token is refused by the lab-management endpoint',
    precondition: 'Seed data loaded (5 accounts, LAB01–LAB03, no booking); clock 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'PATCH /api/labs/LAB01',
        body: { status: 'CLOSED' },
        expect: { status: 403, body: { error: 'FORBIDDEN' } },
      },
    ],
  },
];

// Test Statistics sheet (Report 5.2): sub totals of the three features.
// Applicable cases = 25 − 4 N/A = 21.
const STATS = {
  passed: 16,               // 6 + 8 + 2
  failed: 3,                // 1 + 2 + 0
  pending: 2,               // 1 + 0 + 1
  na: 4,                    // 0 + 2 + 2
  total: 25,                // 8 + 12 + 5
  testCoverage: 90.48,      // (16 + 3) × 100 / 21 = 90.476…
  successfulCoverage: 76.19, // 16 × 100 / 21 = 76.190…
  round2Column: 'I',        // Round 1 = F, Round 2 = I, Round 3 = L
};

